mapper.select:

WHERE del_flag = '0'



            AND generate_affirm = 1
            AND upload_affirm = 1


            AND (generate_affirm = 0 OR upload_affirm = 0)




    and is_last = #{isLast}


    AND template_id in

        #{templateId}



    AND coc_template_no LIKE CONCAT('%', #{cocTemplateNo}, '%')


    AND wvta_coc_no LIKE CONCAT('%', #{wvtaCocNo}, '%')


    and version like concat('%', #{version}, '%')


    and REPLACE(tvv, ',', '') like concat('%', #{tvv}, '%')


    AND model_no LIKE CONCAT('%', #{modelNo}, '%')


    AND vehicle_type = #{vehicleType}


    and effective_date >= #{effectiveDateStart}


    and effective_date <= #{effectiveDateEnd}


    and overdue_date >= #{overdueDateStart}


    and overdue_date <= #{overdueDateEnd}


    and remark like concat('%', #{remark}, '%')


    AND status = #{status}


    AND validate_result in

        #{validateResult}



    and generate_affirm = #{generateAffirm}


    and upload_affirm = #{uploadAffirm}


    and uuid = #{uuid}

${params.dataScope}
ORDER BY create_time DESC

mapper.update:
UPDATE vehicle_template SET validate_result = CASE template_id
WHEN #{item.templateId} THEN #{item.validateResult}
END, validate_msg = CASE template_id
WHEN #{item.templateId} THEN #{item.validateMsg}
END, validate_time = SYSDATE() WHERE template_id IN
#{item.templateId}

mapper.select:
SELECT vt.template_id, vt.wvta_coc_no, vt.coc_template_no, vt.model_no, vt.version, vt.vehicle_type, vt.status, vt.validate_result, vt.validate_time, vt.validate_msg, vt.json, vt.remark, vt.create_by, vt.create_time, vt.update_by, vt.update_time, vt.filepath, vt.is_last, vt.uuid, vt.overdue_date, vt.template_version, vt.effective_date, vt.tvv FROM vehicle_template vt INNER JOIN sys_dict_data sdd ON sdd.dict_type = 'reminder_time' AND sdd.status = '0' and dict_sort = 0 WHERE vt.del_flag = '0' AND vt.overdue_date IS NOT NULL
and expired_notice = #{needExpiredNotice}
AND TIMESTAMPDIFF(MICROSECOND, NOW(), vt.overdue_date) / 1000 <= CAST(sdd.dict_value AS SIGNED) AND vt.overdue_date > NOW()

mapper.update:
update vehicle_template set status = '0'
where status = '1' and effective_date <= NOW()
AND (SELECT dict_value FROM sys_dict_data WHERE dict_type = 'auto_status' AND dict_sort = 0) = '1';

UPDATE vehicle_template SET no_next_version_notice = #{status}, update_time = NOW() WHERE template_id IN
#{id}
AND del_flag = '0'

UPDATE vehicle_template SET expired_notice = #{status}, update_time = NOW() WHERE template_id IN
#{id}
AND del_flag = '0'

UPDATE vehicle_info
SET vehicle_template_id = #{templateId}
WHERE vin = #{vin}

